function fitMapToData() {
  map.invalidateSize(true);
  try {
    const subLayers = layers.subs && layers.subs.getLayers ? layers.subs.getLayers() : [];
    if (subLayers.length) {
      const fg = L.featureGroup(subLayers);
      if (fg.getBounds().isValid()) {
        map.fitBounds(fg.getBounds().pad(0.04));
      } else {
        map.setView(STAUNTON_CENTER, 13);
      }
    } else {
      map.setView(STAUNTON_CENTER, 13);
    }
  } catch (err) {
    console.warn("fitMapToData fallback:", err);
    map.setView(STAUNTON_CENTER, 13);
  }
  refreshSubdivisionLabels();
  refreshNeighborhoodLabel();
}

window.addEventListener("load", () => {
  map.invalidateSize(true);
  if (layers.subs) fitMapToData();
});

