function syncFamilyLayerMembership() {
  Object.keys(familyLayers).forEach(name => {
    const lg = familyLayers[name];
    const wantOnMap = viewMode === "neighborhoods"
      ? inResidentialSubdivisionView(name)
      : isAcceptedPublicSubdivision(name);
    const onSubs = layers.subs && layers.subs.hasLayer(lg);
    if (wantOnMap && !onSubs) layers.subs.addLayer(lg);
    if (!wantOnMap && onSubs) layers.subs.removeLayer(lg);
  });
  rebuildMemberHitLayer();
}

